/* Tome offline worker — generated by vite.config.ts (offlineWorker). Do not edit dist/sw.js by hand. */
const VERSION = '__VERSION__';
const SHELL = __SHELL__;
const SHELL_CACHE = `tome-shell-${VERSION}`;
const RUNTIME_CACHE = 'tome-runtime-v1'; // Python runtime, piano samples, KaTeX fonts: kept across versions

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(SHELL_CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('tome-shell-') && k !== SHELL_CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

const NETWORK_FIRST = ['/catalog.json', '/trusted-keys.json'];

// Fetched once, then always from the cache: these never change within a version of the player.
const RUNTIME = [/^\/pyodide\//, /^\/soundfont\//, /^\/assets\/.*\.(woff|ttf)$/];

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // the platform API, and anything else, goes straight to the network
  // Store cover pictures: shown from the cache at once (and offline), refreshed in the background.
  if (/^\/courses\/[^/]+\/assets\/images\/cover\.[a-z]+$/.test(url.pathname)) {
    e.respondWith((async () => {
      const cache = await caches.open(RUNTIME_CACHE);
      const hit = await cache.match(req);
      const fresh = fetch(req).then((res) => { if (res.ok) cache.put(req, res.clone()); return res; });
      if (hit) { e.waitUntil(fresh.catch(() => {})); return hit; }
      return fresh;
    })());
    return;
  }
  // Store downloads and developer courses must always be fresh.
  if (url.pathname.startsWith('/bundles/') || url.pathname.startsWith('/courses/') || url.pathname.startsWith('/__preview/')) return;

  if (req.mode === 'navigate') {
    // The app is one page with #routes: online, take the newest page; offline, the cached one.
    e.respondWith(fetch(req).catch(() => caches.match('/index.html', { cacheName: SHELL_CACHE })));
    return;
  }
  if (RUNTIME.some((r) => r.test(url.pathname))) {
    e.respondWith((async () => {
      const cache = await caches.open(RUNTIME_CACHE);
      const hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }
  if (NETWORK_FIRST.includes(url.pathname)) {
    // Can change without a new player build: prefer the network, fall back to the copy from install time.
    e.respondWith(fetch(req).then((res) => { if (res.ok) { const copy = res.clone(); caches.open(SHELL_CACHE).then((c) => c.put(req, copy)); } return res; })
      .catch(() => caches.match(req)));
    return;
  }
  e.respondWith(caches.match(req).then((hit) => hit ?? fetch(req)));
});
